class Solution {
public:
    string minRemoveToMakeValid(string s) {
        unordered_set<int> remove_indices;
        vector<int> st;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') st.push_back(i);
            else if (s[i] == ')') {
                if (!st.empty()) st.pop_back();
                else remove_indices.insert(i);
            }
        }
        for (int idx : st) remove_indices.insert(idx);
        string res;
        for (int i = 0; i < (int)s.size(); i++) {
            if (remove_indices.find(i) == remove_indices.end()) {
                res.push_back(s[i]);
            }
        }
        return res;
    }
};

class Solution {
    public String minRemoveToMakeValid(String s) {
        boolean[] remove = new boolean[s.length()];
        int[] st = new int[s.length()];
        int top = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') st[top++] = i;
            else if (ch == ')') {
                if (top > 0) top--;
                else remove[i] = true;
            }
        }
        while (top > 0) remove[st[--top]] = true;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            if (!remove[i]) sb.append(s.charAt(i));
        }
        return sb.toString();
    }
}

var minRemoveToMakeValid = function(s) {
    const removeIndices = new Set();
    const st = [];
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') st.push(i);
        else if (s[i] === ')') {
            if (st.length > 0) st.pop();
            else removeIndices.add(i);
        }
    }
    for (const idx of st) removeIndices.add(idx);
    const res = [];
    for (let i = 0; i < s.length; i++) {
        if (!removeIndices.has(i)) res.push(s[i]);
    }
    return res.join('');
};
